// Calculate the average actualNetWeight dynamically 
let totalWeight = 0;
let count = 0;
let lastWeight =0;

for (let i = 0  ; i < packstemp.length; i++) {
    let el = packstemp[i];
    if (el.actualNetWeight !== null) {
        totalWeight += el.actualNetWeight;
        flow.set('lastWeight',el.actualNetWeight);
        count++;
    }
}

// Calculate the average weight
let averageWeight = count > 0 ? parseFloat((totalWeight / count).toFixed(2)) : 0;
flow.set('averageWeight',averageWeight);

// Get the current timestamp
let currentTimestamp = new Date().toLocaleString('en-US', { 
    year: 'numeric', 
    month: '2-digit', 
    day: '2-digit', 
    hour: '2-digit', 
    minute: '2-digit', 
    second: '2-digit'
});

// Add the current average weight and timestamp to the average weight data array
averageWeightData.unshift({
    timestamp: currentTimestamp,
    averageWeight: averageWeight
});

